import { useEffect, useState } from "react";
import axios from "axios";
import AdminPanel from "./components/AdminPanel";
import AuthPage from "./components/Authpage";

import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";
import { Bar } from "react-chartjs-2";

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
);

const API_URL = "http://localhost:5000";

function App() {
  const [candidates, setCandidates] = useState([]);
  const [darkMode, setDarkMode] = useState(false);
  const [showResults, setShowResults] = useState(false);
  const [electionClosed, setElectionClosed] = useState(false);
  const [selectedVotes, setSelectedVotes] = useState({});
  const [editId, setEditId] = useState(null);

  const [auth, setAuth] = useState({
    token: localStorage.getItem("token") || null,
    role: localStorage.getItem("role") || null,
  });

  const [candidateForm, setCandidateForm] = useState({
    firstName: "",
    lastName: "",
    candidacy: "",
    description: "",
    image: null,
  });

  const [message, setMessage] = useState("");

  // ================= FETCH =================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch {
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    setAuth({ token: null, role: null });
  };

  // ================= SAVE CANDIDATE =================
  const handleSaveCandidate = async () => {
    try {
      const formData = new FormData();
      formData.append("firstName", candidateForm.firstName);
      formData.append("lastName", candidateForm.lastName);
      formData.append("candidacy", candidateForm.candidacy);
      formData.append("description", candidateForm.description || "");
      if (candidateForm.image) formData.append("image", candidateForm.image);

      if (editId) {
        await axios.put(`${API_URL}/api/candidates/${editId}`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate updated.");
      } else {
        await axios.post(`${API_URL}/api/candidates`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate added.");
      }

      setCandidateForm({
        firstName: "",
        lastName: "",
        candidacy: "",
        description: "",
        image: null,
      });

      setEditId(null);
      fetchCandidates();
    } catch {
      setMessage("Failed to save candidate.");
    }
  };

  const handleDeleteCandidate = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/candidates/${id}`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });
      fetchCandidates();
    } catch {
      setMessage("Delete failed.");
    }
  };

  // ================= VOTE =================
  const handleSelect = (position, candidateId) => {
    setSelectedVotes({
      ...selectedVotes,
      [position]: candidateId,
    });
  };

  const handleVoteCast = async () => {
    if (electionClosed) return;

    const confirmVote = window.confirm(
      "Are you sure you want to cast your vote?"
    );
    if (!confirmVote) return;

    try {
      for (let position in selectedVotes) {
        await axios.post(
          `${API_URL}/api/vote/${selectedVotes[position]}`,
          {},
          { headers: { Authorization: `Bearer ${auth.token}` } }
        );
      }

      setMessage("Vote successfully cast!");
      setSelectedVotes({});
      fetchCandidates();
    } catch {
      setMessage("Voting failed.");
    }
  };

  const groupedCandidates = candidates.reduce((acc, candidate) => {
    const key = candidate.candidacy || "Other";
    if (!acc[key]) acc[key] = [];
    acc[key].push(candidate);
    return acc;
  }, {});

  if (!auth.token) return <AuthPage setAuth={setAuth} />;

  // ================= THEME STYLES =================
  const theme = {
    background: darkMode ? "#1f1f2e" : "#f4f4f9",
    card: darkMode ? "#2c2c3a" : "#ffffff",
    text: darkMode ? "#f4f4f9" : "#1f1f2e",
    button: darkMode ? "#4f46e5" : "#6366f1",
    buttonText: "#ffffff",
    voteButton: darkMode ? "#10b981" : "#16a34a",
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        backgroundColor: theme.background,
        color: theme.text,
        padding: 20,
        fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif",
      }}
    >
      {/* HEADER */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: 20,
        }}
      >
        <h1 style={{ margin: 0 }}>🎓 SorSU Online Voting</h1>

        <div>
          <button
            onClick={() => setDarkMode(!darkMode)}
            style={{
              marginRight: 10,
              padding: "8px 16px",
              backgroundColor: theme.button,
              color: theme.buttonText,
              border: "none",
              borderRadius: 5,
              cursor: "pointer",
            }}
          >
            {darkMode ? "Light Mode" : "Dark Mode"}
          </button>

          <button
            onClick={handleLogout}
            style={{
              padding: "8px 16px",
              backgroundColor: "#ef4444",
              color: "#ffffff",
              border: "none",
              borderRadius: 5,
              cursor: "pointer",
            }}
          >
            Logout
          </button>
        </div>
      </div>

      {message && (
        <p
          style={{
            backgroundColor: darkMode ? "#3b3b4f" : "#fee2e2",
            color: darkMode ? "#f4f4f9" : "#b91c1c",
            padding: "10px 15px",
            borderRadius: 5,
          }}
        >
          {message}
        </p>
      )}

      {/* ADMIN CONTROLS */}
      {auth.role === "admin" && (
        <div style={{ marginBottom: 20 }}>
          <button
            onClick={() => setElectionClosed(!electionClosed)}
            style={{
              marginRight: 10,
              padding: "8px 16px",
              backgroundColor: theme.button,
              color: theme.buttonText,
              border: "none",
              borderRadius: 5,
              cursor: "pointer",
            }}
          >
            {electionClosed ? "Open Election" : "Close Election"}
          </button>

          {electionClosed && (
            <button
              onClick={() => setShowResults(!showResults)}
              style={{
                padding: "8px 16px",
                backgroundColor: theme.button,
                color: theme.buttonText,
                border: "none",
                borderRadius: 5,
                cursor: "pointer",
              }}
            >
              {showResults ? "Hide Results" : "View Results"}
            </button>
          )}
        </div>
      )}

      {/* ADMIN PANEL */}
      {auth.role === "admin" && !showResults && (
        <AdminPanel
          candidateForm={candidateForm}
          setCandidateForm={setCandidateForm}
          onSave={handleSaveCandidate}
          editId={editId}
          setEditId={setEditId}
          onDelete={handleDeleteCandidate}
          theme={theme} // optional: you can pass theme for styling inside AdminPanel
        />
      )}

      {/* RESULTS */}
      {showResults ? (
        <div>
          <h2>📊 Election Results</h2>

          {Object.entries(groupedCandidates).map(([position, list]) => {
            const sorted = [...list].sort(
              (a, b) => (b.votes || 0) - (a.votes || 0)
            );

            const data = {
              labels: sorted.map((c) => `${c.firstName} ${c.lastName}`),
              datasets: [
                {
                  label: `${position} Votes`,
                  data: sorted.map((c) => c.votes || 0),
                  backgroundColor: theme.button,
                },
              ],
            };

            return (
              <div
                key={position}
                style={{
                  marginBottom: 40,
                  backgroundColor: theme.card,
                  padding: 20,
                  borderRadius: 8,
                }}
              >
                <h3>{position}</h3>
                <Bar data={data} />
              </div>
            );
          })}
        </div>
      ) : (
        auth.role === "user" &&
        !electionClosed && (
          <div>
            <h2>🗳 Cast Your Vote</h2>

            {Object.entries(groupedCandidates).map(([position, list]) => (
              <div
                key={position}
                style={{
                  marginBottom: 20,
                  backgroundColor: theme.card,
                  padding: 15,
                  borderRadius: 8,
                }}
              >
                <h3>{position}</h3>

                {list.map((c) => (
                  <div key={c._id} style={{ marginBottom: 5 }}>
                    <label>
                      <input
                        type="radio"
                        name={position}
                        value={c._id}
                        checked={selectedVotes[position] === c._id}
                        onChange={() => handleSelect(position, c._id)}
                        style={{ marginRight: 8 }}
                      />
                      {c.firstName} {c.lastName}
                    </label>
                  </div>
                ))}
              </div>
            ))}

            <button
              onClick={handleVoteCast}
              style={{
                padding: "10px 20px",
                fontWeight: "bold",
                backgroundColor: theme.voteButton,
                color: "#ffffff",
                border: "none",
                borderRadius: 5,
                cursor: "pointer",
              }}
            >
              Cast Vote
            </button>
          </div>
        )
      )}
    </div>
  );
}

export default App;
